/**
 * Other names for glyphs above: the concept names apps already use (x, loader,
 * credit-card…) and common Lucide spellings (trash-2, log-out, circle-check…),
 * so a migration can keep its names. ICON_NAMES lists real glyphs only.
 */
export const ICON_ALIASES = {
  x: 'close',
  'alert-triangle': 'alert',
  'more-horizontal': 'more',
  loader: 'spinner',
  zap: 'bolt',
  'bar-chart': 'bars',
  'credit-card': 'card',
  'phone-off': 'phone-end',
  'graduation-cap': 'graduation',
  sparkles: 'sparkle',
  message: 'chat',
  'trash-2': 'trash',
  'log-out': 'logout',
  'log-in': 'login',
  'circle-check': 'check-circle',
  'triangle-alert': 'alert',
  'circle-alert': 'alert-circle',
  'loader-2': 'spinner',
  'loader-circle': 'spinner',
  ellipsis: 'more',
  'ellipsis-vertical': 'more-vertical',
  'circle-help': 'help-circle',
  'circle-x': 'x-circle',
  'circle-plus': 'plus-circle',
  'circle-minus': 'minus-circle',
  'square-check': 'check-square',
  'message-circle': 'chat',
  'message-square': 'chat',
  'layout-dashboard': 'dashboard',
  landmark: 'bank',
  'dollar-sign': 'dollar',
  'circle-dollar-sign': 'dollar-circle',
  house: 'home',
  cog: 'settings',
  pen: 'pencil',
  edit: 'pencil',
  'chart-candlestick': 'candlestick-chart',
  'chart-line': 'line-chart',
  'chart-pie': 'pie-chart',
  'chart-bar': 'bars',
  'chart-column': 'bars',
  'volume-2': 'volume',
  'volume-x': 'volume-off',
  'volume-1': 'volume-low',
  'user-round': 'user',
  'users-round': 'users',
  'refresh-cw': 'refresh',
  'rotate-cw': 'refresh',
  'circle-stop': 'stop',
  'radio-tower': 'live',
  'arrow-left-right': 'arrows-left-right',
  'arrow-up-down': 'arrows-up-down',
  'bell-ring': 'bell-ringing',
  fuel: 'gas',
  'file-badge': 'certificate',
  'scroll-text': 'diploma',
  'scan-face': 'face-id',
  backpack: 'student',
  twitter: 'x-twitter',
  'credit-card-2': 'card',
  'circle-play': 'play-circle',
  'shopping-basket': 'shopping-bag',
  'thumbs-up-2': 'thumbs-up',
  'badge-dollar-sign': 'dollar-circle',
} satisfies Record<string, keyof typeof ICONS>;

export type GlyphName = keyof typeof ICONS;
export type IconName = GlyphName | keyof typeof ICON_ALIASES;
export const ICON_NAMES = Object.keys(ICONS) as GlyphName[];

/** The glyph a name draws (aliases resolve to their target). */
export function glyphFor(name: IconName): Glyph {
  return (ICONS as Record<string, Glyph>)[name] ?? ICONS[(ICON_ALIASES as Record<string, GlyphName>)[name]];
}

export type IconTone = 'gradient' | 'current' | 'white';
export type IconProps = Omit<SVGAttributes<SVGSVGElement>, 'name'> & {
  name: IconName;
  size?: number;
  tone?: IconTone;
  /** Accessible name. Omit for decorative icons (they get aria-hidden). */
  label?: string;
};

export function Icon({ name, size = 24, tone = 'gradient', label, className, style, ...rest }: IconProps) {
  const g = glyphFor(name);
  return (
    <svg
      viewBox="0 0 24 24"
      className={cx('cx-icon', `cx-icon--${tone}`, className)}
      style={{ ['--size' as string]: `${size}px`, ...style }}
      role={label ? 'img' : undefined}
      aria-label={label}
      aria-hidden={label ? undefined : true}
      {...rest}
    >
      {g.b && <path className="b" d={g.b} />}
      {g.s && <path className="s" d={g.s} />}
      {g.f && <path className="f" d={g.f} />}
    </svg>
  );
}

export type IconTileProps = { name: IconName; variant?: 'brand' | 'glass' | 'outline'; size?: 'sm' | 'md' | 'lg'; label?: string; className?: string };
/** The site's ember icon square (brand), or a quieter glass / outline tile. */
export function IconTile({ name, variant = 'brand', size = 'md', label, className }: IconTileProps) {
  return (
    <span className={cx('cx-itile', `cx-itile--${variant}`, size !== 'md' && `cx-itile--${size}`, className)}>
      <Icon name={name} tone={variant === 'brand' ? 'white' : 'gradient'} label={label} />
    </span>
  );
}

/**
 * Gradient definitions for every icon. Render once, near the top of <body>.
 * A gradient resolves its colours where it is DEFINED, so each brand renders its own
 * copy inside its data-brand wrapper (<IconDefs brand="worldstreet" />, id cx-ig-worldstreet).
 */
export function IconDefs({ brand }: { brand?: string } = {}) {
  const id = brand ? `cx-ig-${brand}` : 'cx-ig';
  return (
    <svg width="0" height="0" aria-hidden="true" focusable="false" style={{ position: 'absolute' }}>
      <defs>
        {/* userSpaceOnUse: objectBoundingBox gradients vanish on straight strokes */}
        <linearGradient id={id} gradientUnits="userSpaceOnUse" x1="3" y1="2" x2="21" y2="22">
          {/* stop-color as a CSS property, not the presentation attribute: iOS Safari
              doesn't resolve var() in SVG attributes and paints the stop black */}
          <stop offset="0" style={{ stopColor: 'var(--cx-icon-from, var(--cx-amber))' }} />
          <stop offset="1" style={{ stopColor: 'var(--cx-icon-to, var(--cx-ember))' }} />
        </linearGradient>
        {!brand && (
          <linearGradient id="cx-ig-white" gradientUnits="userSpaceOnUse" x1="3" y1="2" x2="21" y2="22">
            <stop offset="0" style={{ stopColor: '#ffffff' }} />
            <stop offset="1" style={{ stopColor: '#ffffff', stopOpacity: 0.78 }} />
          </linearGradient>
        )}
      </defs>
    </svg>
  );
}
